query FactsChecks($owner: String!, $name: String!, $number: Int!, $after: String) {
  repository(owner: $owner, name: $name) {
    pullRequest(number: $number) {
      headRefOid
      mergeQueueEntry { position }
      commits(last: 1) {
        nodes {
          commit {
            oid
            statusCheckRollup {
              contexts(first: 100, after: $after) {
                totalCount
                pageInfo { hasNextPage endCursor }
                nodes {
                  __typename
                  ... on StatusContext { id }
                  ... on CheckRun {
                    id databaseId name conclusion status startedAt completedAt detailsUrl
                    checkSuite { conclusion app { databaseId } workflowRun { databaseId file { path } } }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

